import numpy as np

def compute_margins(rmse_baseline: dict, rmse_scaling: dict, tol: float = 1e-12) -> dict:
    results = {}
    for family in rmse_baseline:
        if family not in rmse_scaling:
            continue
        margin = rmse_baseline[family] - rmse_scaling[family]
        results[family] = {
            "margin": margin,
            "tie": bool(abs(margin) <= tol)
        }
    return results

# Example
rmse_baseline = {"family_A": 0.123456789, "family_B": 0.5}
rmse_scaling  = {"family_A": 0.123456789, "family_B": 0.4}
print(compute_margins(rmse_baseline, rmse_scaling))
# {'family_A': {'margin': 0.0, 'tie': True}, 'family_B': {'margin': 0.09999999999999998, 'tie': False}}
